  CorporateLanguageTerm(
    term: 'Variance',
    fullForm: '—',
    meaning: 'Difference between actual performance and a budget, target or prior period.',
    whereSeen: 'Finance, operations',
    bridge: 'Always ask whether favourable or unfavourable and why.',
    category: 'Finance & Accounting',
    priorityTier: 1,
    indianContext: 'Variance analysis is a staple of Indian management reviews, where finance walks through where actual numbers diverged from budget or forecast and asks the responsible manager to explain why, and whether the deviation is favourable or unfavourable. It is one of the main mechanisms through which accountability for numbers gets enforced in a company.',
