  CorporateLanguageTerm(
    term: 'Leverage',
    fullForm: '—',
    meaning: 'Use of debt or other fixed financial commitments to increase potential returns and risk.',
    whereSeen: 'Finance, M&A',
    bridge: 'Higher leverage can magnify both gains and losses.',
    category: 'Finance & Accounting',
    indianContext: 'Leverage — how much a company relies on borrowed money relative to its own capital — is closely watched by Indian finance teams, lenders and boards because higher leverage magnifies both potential gains and potential losses, and can constrain flexibility during downturns. It\'s a common topic in M&A financing structures and in credit discussions with banks.',
